#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float stroke_scale;     // 2..16
    float wax_mix;          // 0..1
    float paper_mix;        // 0..1
    float color_bleed;      // 0..1
    float direction_var;    // 0..1
};

struct VIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VOut { float4 pos [[position]]; float2 uv; };

vertex VOut main0(VIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float luma(float3 c){ return dot(c, float3(0.2126,0.7152,0.0722)); }

fragment float4 fragment_main(VOut in [[stage_in]], texture2d<float> src [[texture(0)]], constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 pix = in.uv * u.OutputSize.xy;
    float2 texel = 1.0 / u.OutputSize.xy;
    float3 c0 = src.sample(s, in.uv).rgb;

    // Image gradients
    float3 s00 = src.sample(s, in.uv + float2(-1,-1)*texel).rgb;
    float3 s10 = src.sample(s, in.uv + float2( 0,-1)*texel).rgb;
    float3 s20 = src.sample(s, in.uv + float2( 1,-1)*texel).rgb;
    float3 s01 = src.sample(s, in.uv + float2(-1, 0)*texel).rgb;
    float3 s21 = src.sample(s, in.uv + float2( 1, 0)*texel).rgb;
    float3 s02 = src.sample(s, in.uv + float2(-1, 1)*texel).rgb;
    float3 s12 = src.sample(s, in.uv + float2( 0, 1)*texel).rgb;
    float3 s22 = src.sample(s, in.uv + float2( 1, 1)*texel).rgb;

    float3 gX = (s20 + 2.0*s21 + s22) - (s00 + 2.0*s01 + s02);
    float3 gY = (s02 + 2.0*s12 + s22) - (s00 + 2.0*s10 + s20);
    float2 grad = float2(luma(gX), luma(gY));
    float gradMag = length(grad);

    // Stroke direction: perpendicular to gradient, with noise-based variance
    float t = float(u.FrameCount) * 0.011;
    float n = fract(sin(dot(pix, float2(12.9898,78.233))) * 43758.5453 + t);
    float angle = atan2(grad.y, grad.x) + (1.5708) + (n - 0.5)*u.direction_var*3.14159;
    float2 dir = float2(cos(angle), sin(angle));

    // Stroke pattern: repeated lines along dir
    float scale = clamp(u.stroke_scale, 2.0, 16.0);
    float v = fract(dot(pix, dir)/scale);
    float line = smoothstep(0.45, 0.5, v) * (1.0 - smoothstep(0.5, 0.55, v));
    // Modulate by gradient magnitude to emphasize edges less (crayon fills flatter areas)
    line *= smoothstep(0.8, 0.2, gradMag);

    // Wax mix: blend towards a waxy flat fill using neighborhood average
    float3 acc = float3(0.0); float wsum = 0.0;
    int r = 2;
    for(int y=-r;y<=r;++y){ for(int x=-r;x<=r;++x){
        float2 o = float2(x,y); float w = exp(-dot(o,o)*0.2);
        float3 s3 = src.sample(s, in.uv + o*texel).rgb; acc += s3*w; wsum += w; }}
    float3 wax = (wsum>0.0)? acc/wsum : c0;

    // Color bleed: mix towards local chroma average
    float L0 = luma(c0);
    float3 chroma = normalize(max(float3(1e-3), c0));
    float3 bleed = normalize(max(float3(1e-3), wax));
    float3 crayon = mix(c0, wax, u.wax_mix);
    crayon = mix(crayon, float3(L0)*bleed, u.color_bleed*0.5);

    // Paper texture
    float noise = fract(sin(dot(pix, float2(91.345,47.123))) * 12534.123 + t*0.73);
    float3 paper = mix(float3(1.0), float3(0.97,0.95,0.92), 0.25 + 0.25*noise);

    // Composite: stroke darkens the wax/crayon base
    float3 outc = crayon;
    outc = mix(outc, outc*0.5, clamp(line*1.5, 0.0, 1.0));
    outc = mix(outc, paper, clamp(u.paper_mix, 0.0, 1.0));

    return float4(saturate(outc), 1.0);
}

